import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Limit } from '../types'

const limits = atom({ plugin: 'usage-meter', key: 'limits' } as const, [] as Limit[])

const WINDOWS = [
  { kind: 'five_hour', label: 'Session' },
  { kind: 'seven_day', label: 'Week' },
]
const BAR_WIDTH = 8

const colorFor = (percent: number) => {
  if (percent >= 90) {
    return 'red'
  }

  return percent >= 75 ? 'yellow' : 'white'
}

const filledCells = (percent: number) =>
  Math.min(BAR_WIDTH, Math.max(0, Math.round((percent / 100) * BAR_WIDTH)))

const untilReset = (resetsAt: string | undefined, now: number) => {
  if (resetsAt === undefined) {
    return ''
  }

  const minutes = Math.max(0, Math.round((Date.parse(resetsAt) - now) / 60000))
  const days = Math.floor(minutes / 1440)
  const hours = Math.floor((minutes % 1440) / 60)

  if (days > 0) {
    return ` ${days}d ${hours}h`
  }

  return hours > 0 ? ` ${hours}h ${minutes % 60}m` : ` ${minutes}m`
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    $.ui.status(undefined)
    const usage = await $.session.usage()
    await update($, limits, () => usage.rateLimits)

    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    if (e.changed.includes('rateLimits')) {
      await update($, limits, () => e.rateLimits)
    }

    return next(e)
  })

  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    const current = await read($, limits)
    const rows = WINDOWS.flatMap(w => {
      const found = current.find(limit => limit.kind === w.kind)

      return found === undefined ? [] : [{ ...w, ...found }]
    })

    if (rows.length === 0) {
      return next(e)
    }

    const now = await $.clock.now()
    const { Text } = $.ui.resolve(e)

    return (
      <Text>
        <Text dimColor>{e.props.hint === '' ? '' : `${e.props.hint}   `}</Text>
        {rows.map((row, index) => {
          const color = colorFor(row.percentUsed)
          const filled = filledCells(row.percentUsed)

          return (
            <Text key={row.kind}>
              {index > 0 ? '  ·  ' : ''}
              <Text color="white">{row.label} </Text>
              <Text color={color}>{'━'.repeat(filled)}</Text>
              <Text dimColor>{'─'.repeat(BAR_WIDTH - filled)}</Text>
              <Text color={color}> {Math.round(row.percentUsed)}%</Text>
              <Text dimColor>{untilReset(row.resetsAt, now)}</Text>
            </Text>
          )
        })}
      </Text>
    )
  })
}

